      headers: authHeaders,
      body: { expected_revision: 999, operation_id: 'op-stale-999', level: 1 }
    });
    console.log('Stale revision status:', staleRes.status, 'Expected: 409', 'Current rev:', staleRes.data.current_revision);

    console.log('--- TEST 4: Finish run & idempotency ---');
    const finishOp = 'op-finish-1';
    const finishRes = await req('/api/game/finish', {
      method: 'POST',
      headers: authHeaders,
      body: {
        expected_revision: startRes1.data.revision,
        operation_id: finishOp,
        run_id: 'test-run-polly-1',
        outcome: 'completed',
        level: 10,
        score: 35000,
        snapshot: { score: 35000 }
      }
    });
    console.log('Finish status:', finishRes.status, 'Best score:', finishRes.data.best_score, 'Leaderboard top 1:', finishRes.data.leaderboard[0]);

    console.log('--- TEST 5: Logout ---');
    const logoutRes = await req('/api/auth/logout', { method: 'POST', headers: authHeaders });
    console.log('Logout status:', logoutRes.status);
    const postLogout = await req('/api/auth/me', { headers: authHeaders });
    console.log('Post logout /api/auth/me status:', postLogout.status, 'Expected: 401');

    console.log('ALL TESTS PASSED!');
  } catch (err) {
    console.error('Test failed:', err);
  } finally {
    server.close();
  }
});
