const http = require('http');
const app = require('/app/server.js');

const server = app.listen(0, async () => {
  const port = server.address().port;
  console.log('Test server running on port', port);

  async function req(path, options = {}) {
    return new Promise((resolve, reject) => {
      const opt = Object.assign({
        hostname: '127.0.0.1',
        port: port,
        path: path,
        method: 'GET',
        headers: { 'Content-Type': 'application/json' }
      }, options);

      const request = http.request(opt, res => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          let json = null;
          try { json = JSON.parse(data); } catch (e) { json = data; }
          resolve({ status: res.statusCode, data: json });
        });
      });
      request.on('error', reject);
      if (options.body) {
        request.write(typeof options.body === 'string' ? options.body : JSON.stringify(options.body));
      }
      request.end();
    });
  }

  try {
    console.log('--- TEST 1: Login Polly ---');
    const loginRes = await req('/api/auth/login', {
      method: 'POST',
      body: { email: 'polly@brickfall.test', password: 'password123' }
    });
    console.log('Login status:', loginRes.status, 'User:', loginRes.data.user.email, 'Token len:', loginRes.data.token.length);
    const token = loginRes.data.token;
    const authHeaders = { 'Authorization': 'Bearer ' + token };

    console.log('--- TEST 2: /api/auth/me ---');
    const meRes = await req('/api/auth/me', { headers: authHeaders });
    console.log('Me status:', meRes.status, 'Initials:', meRes.data.user.initials, 'Revision:', meRes.data.user.revision);

    console.log('--- TEST 3: Idempotency & Revision ---');
    const op1 = 'op-test-123';
    const startRes1 = await req('/api/game/start', {
      method: 'POST',
      headers: authHeaders,
      body: { expected_revision: meRes.data.user.revision, operation_id: op1, level: 1 }
    });
    console.log('Start 1 status:', startRes1.status, 'New revision:', startRes1.data.revision);

    // Replay same op id & payload
    const startResReplay = await req('/api/game/start', {
      method: 'POST',
      headers: authHeaders,
      body: { expected_revision: meRes.data.user.revision, operation_id: op1, level: 1 }
    });
    console.log('Start replay status:', startResReplay.status, 'Revision:', startResReplay.data.revision);

    // Replay same op id with different payload -> 400
    const startResDiff = await req('/api/game/start', {
      method: 'POST',
      headers: authHeaders,
      body: { expected_revision: meRes.data.user.revision, operation_id: op1, level: 2 }
    });
    console.log('Start diff payload status:', startResDiff.status, 'Expected: 400');

    // Stale revision test -> 409
    const staleRes = await req('/api/game/start', {
      method: 'POST',
      headers: authHeaders,
      body: { expected_revision: 999, operation_id: 'op-stale-999', level: 1 }
    });
    console.log('Stale revision status:', staleRes.status, 'Expected: 409', 'Current rev:', staleRes.data.current_revision);

    console.log('--- TEST 4: Finish run & idempotency ---');
    const finishOp = 'op-finish-1';
    const finishRes = await req('/api/game/finish', {
      method: 'POST',
      headers: authHeaders,
      body: {
        expected_revision: startRes1.data.revision,
        operation_id: finishOp,
        run_id: 'test-run-polly-1',
        outcome: 'completed',
        level: 10,
        score: 35000,
        snapshot: { score: 35000 }
      }
    });
    console.log('Finish status:', finishRes.status, 'Best score:', finishRes.data.best_score, 'Leaderboard top 1:', finishRes.data.leaderboard[0]);

    console.log('--- TEST 5: Logout ---');
    const logoutRes = await req('/api/auth/logout', { method: 'POST', headers: authHeaders });
    console.log('Logout status:', logoutRes.status);
    const postLogout = await req('/api/auth/me', { headers: authHeaders });
    console.log('Post logout /api/auth/me status:', postLogout.status, 'Expected: 401');

    console.log('ALL TESTS PASSED!');
  } catch (err) {
    console.error('Test failed:', err);
  } finally {
    server.close();
  }
});
"

