const http = require('http');
const app = require('/app/server.js');

const server = app.listen(3000, async () => {
  console.log('Server started on port 3000');

  async function get(path, headers = {}) {
    return new Promise((resolve, reject) => {
      http.get({ hostname: '127.0.0.1', port: 3000, path, headers }, res => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, body: data }));
      }).on('error', reject);
    });
  }

  async function post(path, body, headers = {}) {
    return new Promise((resolve, reject) => {
      const payload = JSON.stringify(body);
      const req = http.request({
        hostname: '127.0.0.1',
        port: 3000,
        path,
        method: 'POST',
        headers: Object.assign({
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(payload)
        }, headers)
      }, res => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          let json = null;
          try { json = JSON.parse(data); } catch (e) { json = data; }
          resolve({ status: res.statusCode, data: json });
        });
      });
      req.on('error', reject);
      req.write(payload);
      req.end();
    });
  }

  try {
    // 1. Static files
    const indexRes = await get('/');
    console.log('GET / status:', indexRes.status, 'Has html:', indexRes.body.includes('BRICKFALL'));
    const cssRes = await get('/styles.css');
    console.log('GET /styles.css status:', cssRes.status, 'Has css:', cssRes.body.includes('--bg-main'));
    const jsRes = await get('/game.js');
    console.log('GET /game.js status:', jsRes.status, 'Has js:', jsRes.body.includes('GameEngine'));
    const physRes = await get('/physics.js');
    console.log('GET /physics.js status:', physRes.status, 'Has physics:', physRes.body.includes('circleAABBOverlap'));
    const drillRes = await get('/drills.js');
    console.log('GET /drills.js status:', drillRes.status, 'Has drills:', drillRes.body.includes('createDrillState'));

    // 2. Levels and Constants
    const levelsRes = await get('/api/levels');
    const lvls = JSON.parse(levelsRes.body);
    console.log('Levels count:', lvls.levels.length, 'Lvl 1 digest:', lvls.levels[0].digest);

    const constsRes = await get('/api/constants');
    const consts = JSON.parse(constsRes.body);
    console.log('Constants count:', consts.constants.length);

    // 3. Leaderboard
    const lbRes = await get('/api/leaderboard');
    const lb = JSON.parse(lbRes.body);
    console.log('Leaderboard top 10 count:', lb.leaderboard.length);
    console.log('Top 3 scores:', lb.leaderboard.slice(0, 3).map(x => x.initials + ':' + x.score));

    // 4. Test Mira login and checkpoint
    const miraLogin = await post('/api/auth/login', { email: 'mira@brickfall.test', password: 'password123' });
    console.log('Mira login status:', miraLogin.status, 'Revision:', miraLogin.data.user.revision, 'Active run level:', miraLogin.data.active_run ? miraLogin.data.active_run.level : null);
    console.log('Mira active run balls count:', miraLogin.data.active_run ? miraLogin.data.active_run.balls.length : 0);

    // 5. Test Dev login and checkpoint
    const devLogin = await post('/api/auth/login', { email: 'dev@brickfall.test', password: 'password123' });
    console.log('Dev login status:', devLogin.status, 'Revision:', devLogin.data.user.revision, 'Active run level:', devLogin.data.active_run ? devLogin.data.active_run.level : null);

    console.log('SERVER TESTS COMPLETED SUCCESSFULLY!');
  } catch (e) {
    console.error('Server test error:', e);
  } finally {
    server.close();
  }
});
"

