const http = require('http');
const crypto = require('crypto');
const app = require('/app/server.js');
const { GameEngine, getWholeSeconds, CONSTANTS } = require('/app/physics.js');
const { createDrillState, createMiraCheckpoint, createDevCheckpoint } = require('/app/drills.js');
const XLSX = require('xlsx');

const wb = XLSX.readFile('/assets/artifacts/brickfall_seed.xlsx');
const bricks = XLSX.utils.sheet_to_json(wb.Sheets['Bricks']);

const server = app.listen(0, async () => {
  const port = server.address().port;
  console.log('Test server running on port', port);

  async function api(path, method = 'GET', body = null, token = null) {
    return new Promise((resolve, reject) => {
      const headers = { 'Content-Type': 'application/json' };
      if (token) headers['Authorization'] = 'Bearer ' + token;
      let payload = null;
      if (body) {
        payload = JSON.stringify(body);
        headers['Content-Length'] = Buffer.byteLength(payload);
      }

      const req = http.request({
        hostname: '127.0.0.1',
        port,
        path,
        method,
        headers
      }, res => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          let json = null;
          try { json = JSON.parse(data); } catch (e) { json = data; }
          resolve({ status: res.statusCode, data: json });
        });
      });
      req.on('error', reject);
      if (payload) req.write(payload);
      req.end();
    });
  }

  let testFailures = 0;
  function assert(condition, message) {
    if (!condition) {
      console.error('FAIL:', message);
      testFailures++;
    } else {
      console.log('PASS:', message);
    }
  }

  try {
    console.log('\n=== SECTION 1: AUTHENTICATION & PLAYER ISOLATION ===');
    // Test sign-in for all 3 users
    const miraAuth = await api('/api/auth/login', 'POST', { email: 'mira@brickfall.test', password: 'password123' });
    assert(miraAuth.status === 200, 'Mira login returns 200');
    assert(miraAuth.data.token.length === 64, 'Token is 64 characters lowercase hex');
    assert(/^[0-9a-f]{64}$/.test(miraAuth.data.token), 'Token matches hex regex');
    assert(miraAuth.data.user.initials === 'MRC', 'Mira initials are MRC');
    assert(miraAuth.data.user.highest_level === 10, 'Mira highest level is 10');
    assert(miraAuth.data.user.best_score === 24500, 'Mira best score is 24500');

    const devAuth = await api('/api/auth/login', 'POST', { email: 'dev@brickfall.test', password: 'password123' });
    assert(devAuth.status === 200, 'Dev login returns 200');
    assert(devAuth.data.user.initials === 'DVP', 'Dev initials are DVP');
    assert(devAuth.data.user.highest_level === 3, 'Dev highest level is 3');
    assert(devAuth.data.user.best_score === 6200, 'Dev best score is 6200');

    const pollyAuth = await api('/api/auth/login', 'POST', { email: 'polly@brickfall.test', password: 'password123' });
    assert(pollyAuth.status === 200, 'Polly login returns 200');
    assert(pollyAuth.data.user.initials === 'PLY', 'Polly initials are PLY');
    assert(pollyAuth.data.user.highest_level === 10, 'Polly highest level is 10');
    assert(pollyAuth.data.user.best_score === 31800, 'Polly best score is 31800');

    // Wrong password test
    const wrongAuth = await api('/api/auth/login', 'POST', { email: 'polly@brickfall.test', password: 'wrong' });
    assert(wrongAuth.status === 401, 'Wrong password returns 401');

    // Untrusted client id test
    const meRes = await api('/api/auth/me', 'GET', null, pollyAuth.data.token);
    assert(meRes.data.user.id === pollyAuth.data.user.id, 'User id authenticated solely from bearer token');

    console.log('\n=== SECTION 2: CHECKPOINTS & SEEDED FIXTURES ===');
    assert(miraAuth.data.active_run !== null, 'Mira has active paused checkpoint');
    assert(miraAuth.data.active_run.level === 8, 'Mira checkpoint level is 8');
    assert(miraAuth.data.active_run.score === 24500, 'Mira checkpoint score is 24500');
    assert(miraAuth.data.active_run.lives === 1, 'Mira checkpoint lives is 1');
    assert(miraAuth.data.active_run.combo === 4, 'Mira checkpoint combo is 4');
    assert(miraAuth.data.active_run.power === 'wide', 'Mira checkpoint power is wide');
    assert(miraAuth.data.active_run.paddle_width === 177, 'Mira checkpoint paddle width is 177');

    assert(devAuth.data.active_run !== null, 'Dev has active paused checkpoint');
    assert(devAuth.data.active_run.level === 3, 'Dev checkpoint level is 3');
    assert(devAuth.data.active_run.score === 19950, 'Dev checkpoint score is 19950');
    assert(devAuth.data.active_run.lives === 3, 'Dev checkpoint lives is 3');
    assert(devAuth.data.active_run.combo === 1, 'Dev checkpoint combo is 1');
    assert(devAuth.data.active_run.next_extra_life === 20000, 'Dev checkpoint next_extra_life is 20000');

    // Polly personal runs
    const pollyRunsRes = await api('/api/runs', 'GET', null, pollyAuth.data.token);
    assert(pollyRunsRes.data.runs.length === 10, 'Polly personal runs stores exactly 10 snapshots');
    assert(pollyRunsRes.data.runs[0].run_id === 'polly-archive-11', 'Newest Polly run is archive-11');
    assert(pollyRunsRes.data.runs[9].run_id === 'polly-archive-02', '10th Polly run is archive-02 (01 pruned)');

    // Global leaderboard
    const lbRes = await api('/api/leaderboard');
    assert(lbRes.data.leaderboard.length === 10, 'Leaderboard limit is exactly 10');
    assert(lbRes.data.leaderboard[0].initials === 'ARC' && lbRes.data.leaderboard[0].score === 42000, 'Top 1 is ARC 42000');
    assert(lbRes.data.leaderboard[1].initials === 'PLY' && lbRes.data.leaderboard[1].score === 31800, 'Top 2 is PLY 31800');
    assert(lbRes.data.leaderboard[2].initials === 'NOV' && lbRes.data.leaderboard[2].score === 28000, 'Top 3 is NOV 28000');
    assert(lbRes.data.leaderboard[3].initials === 'MRC' && lbRes.data.leaderboard[3].score === 24500, 'Top 4 is MRC 24500');
    assert(lbRes.data.leaderboard[9].initials === 'RAY' && lbRes.data.leaderboard[9].score === 12000, '10th is RAY 12000');
    assert(!lbRes.data.leaderboard.some(x => x.initials === 'DVP'), 'Top 10 omits DVP 6,200');

    console.log('\n=== SECTION 3: REVISIONS, IDEMPOTENCY & TAB COORDINATION ===');
    const startOpId = 'op-tab1-' + Date.now();
    const pollyRev0 = pollyAuth.data.user.revision;

    // Start level 1
    const pollyStart1 = await api('/api/game/start', 'POST', {
      expected_revision: pollyRev0,
      operation_id: startOpId,
      level: 1
    }, pollyAuth.data.token);
    assert(pollyStart1.status === 200, 'Start returns 200');
    assert(pollyStart1.data.revision === pollyRev0 + 1, 'Revision increments to ' + (pollyRev0 + 1));

    // Replay same op id & payload -> idempotent receipt
    const pollyStartReplay = await api('/api/game/start', 'POST', {
      expected_revision: pollyRev0,
      operation_id: startOpId,
      level: 1
    }, pollyAuth.data.token);
    assert(pollyStartReplay.status === 200, 'Idempotent replay returns 200');
    assert(pollyStartReplay.data.revision === pollyRev0 + 1, 'Idempotent replay returns original revision');

    // Replay same op id with different payload -> 400
    const pollyStartDiff = await api('/api/game/start', 'POST', {
      expected_revision: pollyRev0,
      operation_id: startOpId,
      level: 2
    }, pollyAuth.data.token);
    assert(pollyStartDiff.status === 400, 'Reusing operation id with different payload rejected with 400');

    // Stale revision -> 409 Conflict with authoritative state
    const staleMutation = await api('/api/game/start', 'POST', {
      expected_revision: pollyRev0, // old revision
      operation_id: 'op-tab2-' + Date.now(),
      level: 2
    }, pollyAuth.data.token);
    assert(staleMutation.status === 409, 'Stale revision returns 409 Conflict');
    assert(staleMutation.data.current_revision === pollyRev0 + 1, '409 returns current_revision');
    assert(staleMutation.data.active_run !== undefined, '409 returns authoritative active_run');

    // Retry finish does not duplicate personal record or leaderboard row
    const finishOpId = 'op-finish-' + Date.now();
