    assert(d2.power === 'sticky', 'Drill 2 power is sticky');
    assert(getWholeSeconds(d2.powerSeconds) === 20, 'Drill 2 sticky seconds is 20s');
    assert(d2.advanceSteps(120) === 120, 'Drill 2 advance 2 is 120 steps');
    assert(getWholeSeconds(d2.powerSeconds) === 19, 'Drill 2 sticky seconds is 19s after 240 steps');

    // Drill 3
